// Uniswap V3 Get Quote
import { ethers } from "ethers";
import { CHAIN_CONFIG } from "./uniswap-config";

export async function execute(input) {
  const { chain, tokenIn, tokenOut, amountIn, amountOut, feeTier } = input;

  const config = CHAIN_CONFIG[chain];
  const provider = new ethers.JsonRpcProvider(config.rpcUrl);
  const quoter = new ethers.Contract(config.quoterV2, QUOTER_V2_ABI, provider);

  // Resolve token symbols to addresses + decimals
  const tokenInInfo = await resolveToken(tokenIn, config);
  const tokenOutInfo = await resolveToken(tokenOut, config);

  const isExactOutput = !!amountOut;
  const feeTiers = feeTier ? [feeTier] : [100, 500, 3000, 10000];

  let bestQuote = null;
  let bestFee = null;

  for (const fee of feeTiers) {
    try {
      if (isExactOutput) {
        // exact-output: how much tokenIn needed to get amountOut of tokenOut?
        const amountOutRaw = ethers.parseUnits(amountOut, tokenOutInfo.decimals);
        const params = { tokenIn: tokenInInfo.address, tokenOut: tokenOutInfo.address, amountOut: amountOutRaw, fee, sqrtPriceLimitX96: 0 };
        const q = await quoter.quoteExactOutputSingle.staticCall(params);
        if (!bestQuote || q.amountIn < bestQuote.amountIn) { bestQuote = q; bestFee = fee; }
      } else {
        // exact-input: how much tokenOut from amountIn of tokenIn?
        const amountInRaw = ethers.parseUnits(amountIn, tokenInInfo.decimals);
        const params = { tokenIn: tokenInInfo.address, tokenOut: tokenOutInfo.address, amountIn: amountInRaw, fee, sqrtPriceLimitX96: 0 };
        const q = await quoter.quoteExactInputSingle.staticCall(params);
        if (!bestQuote || q.amountOut > bestQuote.amountOut) { bestQuote = q; bestFee = fee; }
      }
    } catch { continue; }
  }

  if (!bestQuote) throw new Error("No valid route found for this token pair");

  const feeLabel = `${bestFee / 10000}%`;

  if (isExactOutput) {
    return {
      amountIn: ethers.formatUnits(bestQuote.amountIn, tokenInInfo.decimals),
      amountOut,
      priceImpact: bestQuote.priceImpactX96 ? calcPriceImpact(bestQuote) : null,
      fee: feeLabel,
      route: [tokenInInfo.symbol, tokenOutInfo.symbol],
      executionPrice: (Number(amountOut) / Number(ethers.formatUnits(bestQuote.amountIn, tokenInInfo.decimals))).toFixed(6),
      gasEstimate: bestQuote.gasEstimate?.toString()
    };
  } else {
    return {
      amountIn,
      amountOut: ethers.formatUnits(bestQuote.amountOut, tokenOutInfo.decimals),
      priceImpact: bestQuote.priceImpactX96 ? calcPriceImpact(bestQuote) : null,
      fee: feeLabel,
      route: [tokenInInfo.symbol, tokenOutInfo.symbol],
      executionPrice: (Number(ethers.formatUnits(bestQuote.amountOut, tokenOutInfo.decimals)) / Number(amountIn)).toFixed(6),
      gasEstimate: bestQuote.gasEstimate?.toString()
    };
  }
}

// Uniswap V3 Build Transaction (no private key)
import { ethers } from "ethers";
import { SwapRouter02__factory } from "@uniswap/v3-periphery";
import { Percent } from "@uniswap/sdk-core";
import { CHAIN_CONFIG } from "./uniswap-config";

export async function execute(input) {
  const { chain, tokenIn, tokenOut, amountIn, amountOut, recipient, slippageBps = 50, deadline } = input;

  const config = CHAIN_CONFIG[chain];
  const provider = new ethers.JsonRpcProvider(config.rpcUrl);

  const tokenInInfo = await resolveToken(tokenIn, config);
  const tokenOutInfo = await resolveToken(tokenOut, config);

  const isExactOutput = !!amountOut;
  const txDeadline = deadline ?? Math.floor(Date.now() / 1000) + 1200;

  // First: get a quote to determine the counterpart amount + best fee tier
  const { feeTier, amountInRaw, amountOutRaw } = await getBestQuote(
    provider, config, tokenInInfo, tokenOutInfo, amountIn, amountOut
  );

  // Apply slippage to get min/max bounds
  const slippageFactor = BigInt(10000 - slippageBps);
  const amountOutMin = isExactOutput ? amountOutRaw : (amountOutRaw * slippageFactor / 10000n);
  const amountInMax  = isExactOutput ? (amountInRaw  * BigInt(10000 + slippageBps) / 10000n) : amountInRaw;

  // Build calldata using SwapRouter02 exactInputSingle or exactOutputSingle
  const iface = SwapRouter02__factory.createInterface();
  let calldata;

  if (isExactOutput) {
    calldata = iface.encodeFunctionData("exactOutputSingle", [{
      tokenIn: tokenInInfo.address,
      tokenOut: tokenOutInfo.address,
      fee: feeTier,
      recipient,
      amountOut: amountOutRaw,
      amountInMaximum: amountInMax,
      sqrtPriceLimitX96: 0n
    }]);
  } else {
    calldata = iface.encodeFunctionData("exactInputSingle", [{
      tokenIn: tokenInInfo.address,
      tokenOut: tokenOutInfo.address,
      fee: feeTier,
      recipient,
      deadline: txDeadline,
      amountIn: amountInRaw,
      amountOutMinimum: amountOutMin,
      sqrtPriceLimitX96: 0n
    }]);
  }

  const isNativeIn = tokenIn.toUpperCase() === "ETH";
  const value = isNativeIn ? ethers.toBeHex(amountInMax) : "0x0";

  return {
    to: config.swapRouter,
    data: calldata,
    value,
    amountIn: ethers.formatUnits(amountInRaw, tokenInInfo.decimals),
    amountOutMin: ethers.formatUnits(amountOutMin, tokenOutInfo.decimals),
    gasEstimate: await provider.estimateGas({ to: config.swapRouter, data: calldata, value }).then(g => g.toString()).catch(() => null)
  };
}

// Uniswap V3 Pool Info
import { ethers } from "ethers";
import { CHAIN_CONFIG } from "./uniswap-config";

export async function execute(input) {
  const { chain, token0, token1, feeTier = 3000 } = input;

  const config = CHAIN_CONFIG[chain];
  const provider = new ethers.JsonRpcProvider(config.rpcUrl);

  const t0 = await resolveToken(token0, config);
  const t1 = await resolveToken(token1, config);

  const factory = new ethers.Contract(config.factory, FACTORY_ABI, provider);
  const poolAddress = await factory.getPool(t0.address, t1.address, feeTier);

  if (poolAddress === ethers.ZeroAddress) {
    throw new Error(`No pool found for ${t0.symbol}/${t1.symbol} at fee tier ${feeTier}`);
  }

  const pool = new ethers.Contract(poolAddress, POOL_ABI, provider);
  const [slot0, liquidity] = await Promise.all([pool.slot0(), pool.liquidity()]);

  const sqrtPrice = Number(slot0.sqrtPriceX96) / 2 ** 96;
  const price = (sqrtPrice ** 2 * 10 ** (t0.decimals - t1.decimals)).toFixed(6);

  // 24h stats from The Graph subgraph
  const stats = await fetchPoolStats24h(poolAddress, chain);
  const apr = ((stats.fees24h / stats.tvlUSD) * 365 * 100);

  return {
    poolAddress,
    token0: { address: t0.address, symbol: t0.symbol, decimals: t0.decimals },
    token1: { address: t1.address, symbol: t1.symbol, decimals: t1.decimals },
    feeTier,
    liquidity: liquidity.toString(),
    price,
    tvlUSD: stats.tvlUSD,
    volume24h: stats.volume24h,
    fees24h: stats.fees24h,
    apr: Number(apr.toFixed(2))
  };
}

